insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$1901$t$, $t$Andover Borough$t$, $t$SUSSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of occupancy (Housing Standards, Chapter 84 of the Borough Code)$t$, $j$["Issued by: Borough of Andover Enforcement Officer (Construction Official or Sussex County Department of Health officer, per Section 84-1)","Contact: 973-786-6688 ext. 4 · codeenforcement@andoverboroughnj.org","How to apply: The Borough code requires a new certificate of occupancy before a dwelling is occupied by new people, but the Borough website does not describe any resale certificate of occupancy process, form or fee. Call Code Enforcement at (973) 786-6688 ext. 4 to ask whether this is enforced on sales of 1 and 2 family homes.","Inspection by the Enforcement Officer to confirm the dwelling meets the Borough's housing code (New Jersey State Housing Code as adopted)","Certificate states the maximum number of persons allowed to occupy the dwelling","Smoke and carbon monoxide certificate is a separate Borough requirement before a sale (see fire certificate)"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.andoverboroughnj.org/construction-inspections$t$, $j$[{"url":"https://ecode360.com/8925373","label":"Official source (ecode360.com)"},{"url":"https://www.andoverboroughnj.org/construction-inspections/page/smoke-detector-inspections-application-process-residential-units","label":"Official source (andoverboroughnj.org)"}]$j$::jsonb, $t$No person shall occupy as owner or lease or rent to another for occupancy or permit the occupancy of any building or building unit in the Borough of Andover until a certificate of occupancy has been applied for and obtained.$t$, $t$14e022ff7cbf6e302f3fe07fefe2b67f86db2039148cf50cba361a42236d58b3$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":15,"q_ok":1,"q_bad":0,"q_unchecked":14},"source":"property/data/municipal-requirements/checked/1901.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1901.json$t$, true),
  ($t$1901$t$, $t$Andover Borough$t$, $t$SUSSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Andover Borough (Code Enforcement / Housing office) smoke and carbon monoxide certification; fire code enforcing agency is the Sussex County Fire Marshal under a shared services agreement (town fire bureau)","Contact: 973-786-6688 ext. 4 · codeenforcement@andoverboroughnj.org","Apply: Inspectors are available by appointment only and need at least 48 hours' notice. The certificate expires in 6 months and cannot be transferred.","How to apply: Download the Borough's application for one and two family dwelling certification of smoke detector and carbon monoxide detector compliance, complete Part I, and return it to the Borough of Andover, 137 Main Street, Andover, NJ 07821 with the fee payable to Andover Borough. The fee must be paid before the inspection. Questions: (973) 786-6688 ext. 4 or codeenforcement@andoverboroughnj.org.","Fire official in the NJ state directory (county fire marshal), updated 1/12/2026: Mark Snook · (973) 579-0380 · msnook@sussexcountysheriff.com","Smoke alarms on each level, including basements, and outside each separate sleeping area (within 10 feet of each bedroom), all in working order","Smoke alarms listed to ANSI/UL 217; battery-only alarms must be 10-year sealed lithium units; AC-powered alarms from original construction may not be replaced with battery alarms","Smoke alarms older than 10 years (including AC-powered) must be replaced","Carbon monoxide alarm (UL 2034) in the immediate vicinity of each sleeping area, unless there is no attached garage and no fuel-burning appliance","If the home has a secondary power source (permanent generator, solar panels or battery storage), warning labels within 18 inches of the main electrical panel and the electric meter","Fire extinguisher in the kitchen (still mentioned on the Borough web page, but not on the November 2025 application form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide certification, per dwelling","amount":"$75"},{"label":"Re-inspection after a failed inspection","amount":"$40"},{"label":"CSACMAPFEC fee (Borough code Section 66-4H)","amount":"$75"}]$j$::jsonb, $t$https://www.andoverboroughnj.org/media/1761$t$, $t$https://www.andoverboroughnj.org/construction-inspections/page/smoke-detector-inspections-application-process-residential-units$t$, $j$[{"url":"https://www.andoverboroughnj.org/construction-inspections/page/smoke-detector-inspections-application-process-residential-units","label":"Official source (andoverboroughnj.org)"},{"url":"https://www.andoverboroughnj.org/media/1761","label":"Official source (andoverboroughnj.org)"},{"url":"https://ecode360.com/8925027","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/8925128","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Prior to selling a home or changing of tenants, a Certification of Smoke Detector & Carbon Monoxide Alarm Compliance Inspection must be performed.$t$, $t$6a33d87c3eb99845bd8d62f164682659f8c81beedd0a53f18308cc5d61ffa780$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":15,"q_ok":1,"q_bad":0,"q_unchecked":14},"source":"property/data/municipal-requirements/checked/1901.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1901.json$t$, true),
  ($t$1906$t$, $t$Franklin Borough$t$, $t$SUSSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection Permitting Occupancy$t$, $j$["Issued by: Hardyston Township Construction Office, acting as the Construction Official for the Borough of Franklin","Contact: 973-823-7020 ext. 9001 · construction@hardyston.com","Apply: The certificate must be granted or denied within 15 days after the written application is received.","How to apply: Fill out the Application for a Certificate of Inspection Permitting Occupancy (For Resale) from the Hardyston Township website and return it, signed, with payment (checks payable to Hardyston Twp.) to the Hardyston Township Construction Office, 149 Wheatsworth Road, Suite A, Hardyston, NJ 07419. The form asks for the closing date, block and lot, owner and buyer details, and whether the home will be owner occupied or a rental, and lets you choose a full certificate, a certificate for closing purposes only (no occupancy) or a temporary certificate. Review the Certificate of Habitability Check List before the inspection.","Inspection by the Construction Official (or agent) for compliance with Borough ordinances; the official lists the corrections needed","Smoke alarms on all floors and within 10 feet of all sleeping areas; carbon monoxide alarms near sleeping areas","Portable fire extinguisher within 10 feet of the kitchen (checklist still lists it)","GFCI outlets near sinks and in damp locations; cover plates on all receptacles, switches and junction boxes","Sump pumps may not discharge to the town sewer; food disposal grinders are not permitted","Handrails on stairs with three or more risers; guardrails on decks 30 inches or more above grade","Remodeled kitchens, baths and finished basements are checked for permits; open permits must be inspected and approved before the certificate","Attached garage fire-resistive ratings maintained; no basement bedrooms without code egress; no double-keyed deadbolts on the main entrance door","Interior walls, exterior coverings, chimneys and accessory structures (decks, pools, sheds) in good condition and meeting zoning and building codes","If the home converted from oil to gas, the oil tank must have been properly decommissioned","Title may transfer after the application is filed, but no one may move in until all listed corrections are completed; a certificate for closing purposes only (no occupancy) and a temporary certificate (TCO) are options on the form","Also: New water service application on change of ownership: When ownership changes, the new owner must file a new application for Borough water service; the Public Works Committee may discontinue service until it is filed and approved. Charges continue until written notice of the change or transfer of ownership is given.","Also: Open permits and unpermitted work: Open permits must be inspected and approved before the certificate of habitability is issued; remodeled kitchens, baths and finished basements are checked for permits, and the owner must obtain any missing permits and inspections.","Also: Sump pump discharge: Sump pumps cannot discharge into the town sewer; this is checked at the resale inspection.","Also: Oil tank decommissioning: If the home converted from oil to gas, the inspector asks whether the oil tank was properly decommissioned."]$j$::jsonb, $j$[{"label":"Resale certificate of habitability, first tier (code text reads 'Within 10 business days of occupancy')","amount":"$50"},{"label":"Resale, less than 10 but more than 4 business days before occupancy","amount":"$85"},{"label":"Resale, less than 4 business days before occupancy","amount":"$150"},{"label":"Reinspection to abate after the second violation notice, each","amount":"$25"}]$j$::jsonb, $t$https://hardyston.com/wp-content/documents/franklin-boro-resale-form.pdf$t$, $t$https://hardyston.com/franklin-boro-certificate-of-occupancy-compliance/$t$, $j$[{"url":"https://hardyston.com/franklin-boro-certificate-of-occupancy-compliance/","label":"Official source (hardyston.com)"},{"url":"https://hardyston.com/wp-content/documents/franklin-boro-resale-form.pdf","label":"Official source (hardyston.com)"},{"url":"https://hardyston.com/wp-content/documents/franklin-boro-co-checklist.pdf","label":"Official source (hardyston.com)"},{"url":"https://franklinborough.org/index.php/departments/building-and-code-enforcement/building-construction-permits-inspections","label":"Official source (franklinborough.org)"},{"url":"https://ecode360.com/9094560","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/9094620","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Inspections in order to receive a Certificate of Occupancy Compliance for resales and rentals in Franklin Borough have resumed.$t$, $t$0276d34ef2bc2d2a9a33b0e6f2a1e86ff7acbdd68f4697656f019a62bf9eca55$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":17,"q_ok":12,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1906.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1906.json$t$, true),
  ($t$1906$t$, $t$Franklin Borough$t$, $t$SUSSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hardyston Township Construction Office for the Borough of Franklin (smoke/CO checked as part of the resale certificate of habitability); Sussex County Fire Marshal is the fire code enforcing agency","Contact: 973-823-7020 ext. 9001 · construction@hardyston.com","Apply: Same as the resale certificate: decided within 15 days of a complete application; fee tiers by business days before occupancy.","How to apply: No separate smoke/CO certificate application for Franklin Borough was found. The Borough's Fire Marshall page says fire inspections are done through Hardyston Township (973-823-7020, follow the prompts to the Construction Department), and the Hardyston checklist for the resale certificate covers smoke alarms, carbon monoxide alarms and the fire extinguisher. Call the Hardyston Construction Department to confirm whether a separate smoke/CO certificate (and fee) is issued.","Fire official in the NJ state directory (county fire marshal), updated 2/1/2019: Mark Snook · (973) 579-0380 · msnook@sussexcountysheriff.com","Smoke alarms on all floors and within ten feet of all sleeping areas","Carbon monoxide alarms installed and maintained in the immediate vicinity of the sleeping areas","At least one portable fire extinguisher (2-1/2 to 10 pound, ABC type) within 10 feet of the kitchen, top no more than 5 feet above the floor (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://hardyston.com/wp-content/documents/franklin-boro-resale-form.pdf$t$, $t$https://franklinborough.org/index.php/departments/building-and-code-enforcement/fire-marshall$t$, $j$[{"url":"https://franklinborough.org/index.php/departments/building-and-code-enforcement/fire-marshall","label":"Official source (franklinborough.org)"},{"url":"https://hardyston.com/wp-content/documents/franklin-boro-co-checklist.pdf","label":"Official source (hardyston.com)"},{"url":"https://ecode360.com/9094631","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$As of October 2010, the Sussex County Fire Marshall provides Fire prevention services for the Borough.$t$, $t$dccb5e9685c2db173787abc65aec6d92a144e2d60a73ca1d8ae9caed302d81f9$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":17,"q_ok":12,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1906.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1906.json$t$, true),
  ($t$1909$t$, $t$Hamburg Borough$t$, $t$SUSSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for sales and change of tenant (COR)$t$, $j$["Issued by: Construction Official (Hamburg's Construction/Building Department is run by Hardyston Township under a shared service agreement)","Contact: Joe Butto, Construction Official (Hardyston Township, shared service for Hamburg) · 973-823-7020 ext. 9001 · construction@hardyston.com","Apply: The code says the Construction Official inspects within five business days after the written application and fee are received","How to apply: No application form or web page for this certificate was found on the Borough or Hardyston websites. Call the Hardyston Building Department (handles Hamburg construction), 973-823-7020 ext. 9001, construction@hardyston.com, to ask whether a COR inspection is needed for the sale and how to apply.","Inspection by the Construction Official for hazardous, unsanitary or dangerous conditions, using the NJ State Housing Code as the standard","The home must be served by an adequate sewage disposal system and potable water","All construction permits must be closed before the sale","Also: Sump pump certificate (required before closing): Borough Ordinance 17-2024 (Code Ch. 164, Art. XIII): no owner may sell a home without a Department of Public Works certificate that no sump pump or other device is connected to the sanitary sewer. The seller files the application with DPW at least 10 days before the change in ownership. Fee $25; reinspection $25 each. DPW: 973-827-7702, Clerk@hamburgnj.org.","Also: Final water reading: When selling, call the Water/Sewer Department at 973-827-9230 ext. 4011 two weeks before closing to set up the final water reading and sump pump inspection.","Also: Open construction permits: Sellers must make sure all construction permits on the property have been closed (Hardyston Building Department handles Hamburg permits)."]$j$::jsonb, $j$[{"label":"COR, sales and change of tenant (Borough Code section 98-3 fee schedule)","amount":"$35"},{"label":"Reinspection fee to abate","amount":"$25"}]$j$::jsonb, null, $t$https://hamburgnj.org/departments/construction-department/$t$, $j$[{"url":"https://ecode360.com/10215708","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/10215710","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/10215339","label":"Official source (ecode360.com)"},{"url":"https://hamburgnj.org/departments/construction-department/","label":"Official source (hamburgnj.org)"}]$j$::jsonb, $t$No owner, agent, landlord, tenant, corporation or partnership shall allow a new tenant to occupy a dwelling unit until a new certificate of occupancy has been issued for the premises by the Construction Official of the Borough.$t$, $t$0648760458602c7beb6717c77a7067da18acecaae3a188d66b12ca4e12f427a0$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":21,"q_ok":13,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1909.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1909.json$t$, true),
  ($t$1909$t$, $t$Hamburg Borough$t$, $t$SUSSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hardyston Township Fire Prevention Bureau (shared service fire code agency for Hamburg Borough) (town fire bureau)","Contact: Eric A. Stahl, Fire Marshal (Administrative Assistant: Sarah Bright, ext. 9453, sbright@hardyston.com) · 973-823-7020 ext. 9356 · estahl@hardyston.com","Apply: Fee depends on business days before the closing: more than 10 business days for the lowest fee. After you submit, the Bureau calls or emails to schedule within a few business days. Regular inspections are Tuesdays and Wednesdays 9 to 11 AM; rush inspections (less than 4 days) can be scheduled outside those windows. The certificate (inspection) is good for 6 months.","How to apply: Apply and pay online with the Hardyston Fire Prevention Bureau's 'Hamburg and Hardyston - CSACMAPFEC (Residential Smoke Cert)' form (Tyler portal). Give owner, closing date, address, block and lot, and realtor details, and choose paper or email delivery. Paper applications can be picked up at the Construction Office window, Hardyston Municipal Building, 149 Wheatsworth Road. A failed inspection needs a new request form and the $50.00 re-inspection fee.","Fire official in the NJ state directory (town), updated 1/14/2026: Eric A Stahl · (973) 823-7020 · estahl@hardyston.com","Smoke alarms on each level of the premises and outside each separate sleeping area, per NFPA 72","Battery smoke alarms must be 10-year sealed units (ANSI/UL 217); hardwired alarms from original construction cannot be replaced with battery alarms, and hardwired interconnected alarms must stay that way","Carbon monoxide alarm (UL 2034) in the immediate vicinity of the sleeping areas, if the home has a fuel-burning device or attached garage","Warning label (for example 'CAUTION: MULTIPLE SOURCES OF POWER', not handwritten) within 18 inches of the main panel and meter if there is a permanent generator, solar panels or battery storage","All construction permits must be closed with the Construction Department","No portable fire extinguisher needed (the Bureau's regulations say it is no longer required)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate (CSACMAPFEC), more than 10 business days before closing","amount":"$100.00"},{"label":"4 to 10 business days before closing","amount":"$150.00"},{"label":"Less than 4 business days before closing","amount":"$200.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/19de44bf-9a91-401b-94ca-25d7f3d306ab$t$, $t$https://hamburgnj.org/departments/fire-official/$t$, $j$[{"url":"https://hamburgnj.org/departments/fire-official/","label":"Official source (hamburgnj.org)"},{"url":"https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/19de44bf-9a91-401b-94ca-25d7f3d306ab","label":"Official source (hardystonfireprebureaunj.tylerportico.com)"},{"url":"https://hardyston.com/wp-content/documents/forms/Regulations%20-%20CSACMAPFEC%20(Residential%20Smoke%20Cert).pdf","label":"Official source (hardyston.com)"},{"url":"https://hardyston.com/directories/building-and-code-enforcement/fire-prevention-bureau/","label":"Official source (hardyston.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Hamburg Borough has entered into a shared service agreement with Township of Hardyston Fire Prevention Bureau.$t$, $t$7cdaf30728dd3eb042ec8236246dd1548b04657c7e36bed7ebf62f71864d968f$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":21,"q_ok":13,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1909.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1909.json$t$, true),
  ($t$1911$t$, $t$Hardyston Township$t$, $t$SUSSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Hardyston Township Construction Official (Building Department)","Contact: Joe Butto, Construction Official · 973-823-7020 ext. 9001 · construction@hardyston.com","Apply: Apply at least 21 calendar days before the anticipated date of occupancy","How to apply: The code says the owner, purchaser, tenant or occupier applies to the Construction Official on forms from the Building Department at least 21 calendar days before occupancy. No CCO form is posted online; contact the Building Department at the Hardyston Municipal Building, 149 Wheatsworth Road (Mon to Fri 8:30 am to 4:30 pm), 973-823-7020 ext. 9001, construction@hardyston.com. Permits and inspections can also be handled through the Township's Fast Track Gov portal.","Visual inspection by the Construction Official (and subcode officials if needed) for hazardous conditions and outstanding violations of the Uniform Construction Code or Township ordinances","A current zoning permit covering the premises must be issued before the CCO","Smoke detectors must be installed (battery smoke detectors allowed in existing 1-2 family homes)","Inspections may be waived for transfers between immediate family members, or when the home is bought to be demolished and a demolition permit has been applied for","Also: Zoning permit for existing structures: The Certificate of Continued Occupancy is issued only with a current zoning permit covering the premises (Code section 62-13 and 185-85); the fee for a zoning permit for existing structures is $25.","Also: Open construction permits: The Fire Prevention Bureau requires all construction permits to be closed with the Construction Department for the smoke/CO certificate."]$j$::jsonb, $j$[{"label":"Certificate of continued use or occupancy (Code section 88-2F(7)(g))","amount":"$150"},{"label":"Zoning permit for existing structures (Code section 88-3L(1)), needed for the CCO","amount":"$25"},{"label":"Letter stating that no certificate of continued occupancy is required (Code section 88-2F(11))","amount":"$25"}]$j$::jsonb, null, $t$https://hardyston.com/?p=249$t$, $j$[{"url":"https://ecode360.com/10247010","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/10247082","label":"Official source (ecode360.com)"},{"url":"https://hardyston.com/?p=249","label":"Official source (hardyston.com)"}]$j$::jsonb, $t$Purpose. A certificate of continued occupancy shall be required upon the change of ownership or occupancy of any building or portion thereof in the Township of Hardyston.$t$, $t$94e658b909334ea86c4a4ec16813257bc6b233e7ae72ca01461be352ebf55cff$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":19,"q_ok":10,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/1911.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1911.json$t$, true),
  ($t$1911$t$, $t$Hardyston Township$t$, $t$SUSSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hardyston Township Fire Prevention Bureau (town fire bureau)","Contact: Eric A. Stahl, Fire Marshal (direct: ext. 9356, estahl@hardyston.com) · 973-823-7020 Option 7 · fireprevention@hardyston.com","Apply: Fee depends on business days before the closing: more than 10 business days for the lowest fee. After you submit, the Bureau calls or emails to schedule within a few business days. Regular inspections are Tuesdays and Wednesdays 9 to 11 AM; rush inspections (less than 4 days) can be scheduled outside those windows. The certificate (inspection) is good for 6 months.","How to apply: Apply and pay online with the Hardyston Fire Prevention Bureau's 'Hamburg and Hardyston - CSACMAPFEC (Residential Smoke Cert)' form (Tyler portal). Give owner, closing date, address, block and lot, and realtor details, and choose paper or email delivery. Paper applications can be picked up at the Construction Office window, Hardyston Municipal Building, 149 Wheatsworth Road. A failed inspection needs a new request form and the $50.00 re-inspection fee.","Fire official in the NJ state directory (town), updated 6/4/2026: Eric A Stahl · (973) 823-7020 · firemarshal@hardyston.com","Smoke alarms on each level of the premises and outside each separate sleeping area, per NFPA 72","Battery smoke alarms must be 10-year sealed units (ANSI/UL 217); hardwired alarms from original construction cannot be replaced with battery alarms, and hardwired interconnected alarms must stay that way","Carbon monoxide alarm (UL 2034) in the immediate vicinity of the sleeping areas, if the home has a fuel-burning device or attached garage","Warning label (for example 'CAUTION: MULTIPLE SOURCES OF POWER', not handwritten) within 18 inches of the main panel and meter if there is a permanent generator, solar panels or battery storage","All construction permits must be closed with the Construction Department","No portable fire extinguisher needed (the Bureau's regulations say it is no longer required)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate (CSACMAPFEC), more than 10 business days before closing","amount":"$100.00"},{"label":"4 to 10 business days before closing","amount":"$150.00"},{"label":"Less than 4 business days before closing","amount":"$200.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/19de44bf-9a91-401b-94ca-25d7f3d306ab$t$, $t$https://hardyston.com/directories/building-and-code-enforcement/fire-prevention-bureau/$t$, $j$[{"url":"https://hardyston.com/fees-applications/smoke-and-carbon-monoxide-alarm-compliance/","label":"Official source (hardyston.com)"},{"url":"https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/19de44bf-9a91-401b-94ca-25d7f3d306ab","label":"Official source (hardystonfireprebureaunj.tylerportico.com)"},{"url":"https://hardyston.com/wp-content/documents/forms/Regulations%20-%20CSACMAPFEC%20(Residential%20Smoke%20Cert).pdf","label":"Official source (hardyston.com)"},{"url":"https://hardyston.com/directories/building-and-code-enforcement/fire-prevention-bureau/","label":"Official source (hardyston.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Hardyston, CSACMAPFEC (Residential Smoke Cert) Application$t$, $t$678836b5b5039b428cf1191d59faa2c6f615d701774d570d6c726bef4595a61e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":19,"q_ok":10,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/1911.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1911.json$t$, true),
  ($t$1916$t$, $t$Ogdensburg Borough$t$, $t$SUSSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection Permitting Occupancy (Borough code, Building and Housing chapter)$t$, $j$["Issued by: Borough Construction Official or his agent (per the Borough code); the Borough's construction code is enforced by the NJ DCA Northern Regional Office","Contact: Joseph Setticase, Zoning Officer/Code Enforcement Officer · 973-827-3444 · zoning@ogdensburgnj.gov","How to apply: The Borough code says to apply in writing to the Construction Official. The Borough website gives no application form or process for this certificate, and construction code services are run by the NJ DCA Northern Regional Office (NRO.inspectionrequests@dca.nj.gov, 908-713-0722). Call the Borough office at 973-827-3444 to confirm who handles it and how to apply.","Apply in writing to the Construction Official before the rental, transfer of title or occupancy of any dwelling house or dwelling unit","Inspection for compliance with all Borough ordinances, rules and regulations on use and occupancy of dwellings","Title may transfer after the application is filed, but no one may occupy the home until all items marked for correction are completed","Owner or agent must give a reasonable time for the inspection and have someone present to provide entry","Also: Final water reading: The Borough Water Billing Department (973-827-3444 x2) needs a Final Water Reading Request with the exact closing date, the seller's attorney contact and the buyer's name (required to move the account to the buyer). Call if the closing date changes or is cancelled. No fee is shown on the form."]$j$::jsonb, $j$[{"label":"Certificate of inspection permitting occupancy","amount":"$50"}]$j$::jsonb, null, $t$https://ogdensburgnj.org/building-department-state-of-nj/$t$, $j$[{"url":"https://ecode360.com/36213494","label":"Official source (ecode360.com)"},{"url":"https://ogdensburgnj.org/building-department-state-of-nj/","label":"Official source (ogdensburgnj.org)"},{"url":"https://ogdensburgnj.org/departments/zoning-department/","label":"Official source (ogdensburgnj.org)"}]$j$::jsonb, $t$Transfers of title may take place after application of a certificate of inspection for occupancy$t$, $t$198359ddaf1267b4be7de7d9ce9a1399e78063561ceac327bbc814f65fdddd5d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":10,"q_ok":6,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1916.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1916.json$t$, true),
  ($t$1916$t$, $t$Ogdensburg Borough$t$, $t$SUSSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ Department of Community Affairs, Division of Fire Safety, Bureau of Fire Code Enforcement (state-enforced; State LEA for Ogdensburg) (NJ DCA, state)","Contact: Louis Kilmer, Fire Official of record for Ogdensburg (NJ Division of Fire Safety), per the state directory · 609-633-6132 · BFCECodeAdmin@dca.nj.gov","Apply: State fee tiers count business days between the Division's receipt and the closing date: more than ten business days for the lowest fee. If the change of occupant does not happen within 6 months, a new application is needed (per the DCA form).","How to apply: Apply online through the NJ DCA Fire Safety Service Portal (firesolutions.dca.nj.gov): choose Apply for an Application, then Apply for Smoke Certification, fill in the data and pay. Help: BFCECodeAdmin@dca.nj.gov or 609-633-6132. The older DCA paper form goes to PO Box 809, Trenton, NJ 08625-0809 with a check payable to Treasurer, State of New Jersey.","Fire official in the NJ state directory (NJ DCA, state), updated 2/1/2019: Louis Kilmer · (609) 633-6132","Smoke detector on each level of the dwelling, including basements, excluding attic or crawl space (DCA form)","Smoke detector and carbon monoxide alarm outside each separate sleeping area, within 10 feet of bedrooms (DCA form)","All smoke detectors and CO alarms in working order; AC powered or interconnected alarms in homes built after January 1977 must be kept working (DCA form)","Fire extinguisher (form still lists it; dropped from the state requirement in February 2025 by P.L.2025, c.19)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"State smoke/CO certificate, closing more than ten business days after receipt (DCA form, rev. 10/02)","amount":"$35"},{"label":"Received fewer than ten but more than four business days before closing","amount":"$70"},{"label":"Received four business days or fewer before closing","amount":"$125"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/$t$, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/first-time-user-guide/$t$, $j$[{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/first-time-user-guide/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/forms/bfce/certificationinlieu.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Click Apply for Smoke Certification$t$, $t$537e86556d7c17829c7b52664f1be0fd7fc2f561910787068b0ad0f5cfc052da$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":10,"q_ok":6,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1916.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1916.json$t$, true),
  ($t$1918$t$, $t$Sparta Township$t$, $t$SUSSEX$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Sparta Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Michael Wallace, Construction Official / Electrical Subcode · 973-729-9888 · construction@spartanj.org","How to apply: No Township resale Certificate of Continued Occupancy. The Building Department's FAQ says the Township does not require a CCO on the resale of a home; only the smoke detector certification is required (see fire certificate). All building permits must be closed before the smoke certification is released.","Also: Open building permits: All building permits must be closed, and Building Department approval given, before the smoke certification is scheduled and released.","Also: Final water/sewer read (Township utility customers): Sellers on the Township water and sewer utility submit the online 'Final Read Request - New Account Setup' form with the closing date, seller, buyer and both attorneys' contacts; the buyer emails utilities@spartanj.org for final account setup. No fee is shown on the form.","Also: Underground oil tank: The Township does not require removal of a working, non-leaking underground oil tank at sale; any removal is a matter between buyer and seller."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.spartanj.org/190/Building$t$, $j$[{"url":"https://www.spartanj.org/Faq.aspx?QID=69","label":"Official source (spartanj.org)"},{"url":"https://www.spartanj.org/190/Building","label":"Official source (spartanj.org)"}]$j$::jsonb, $t$We do not require a Certificate of Continued Occupancy (CCO) on the resale of a home. A Smoke Detector Certification is required and is performed by the Fire Prevention Department$t$, $t$db3b48ef5edea2c26b54507f7769789e2182f68e47aff18e8c8c51436422bf74$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1918.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1918.json$t$, true),
  ($t$1918$t$, $t$Sparta Township$t$, $t$SUSSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hardyston Township Fire Prevention Bureau (Sparta's fire code enforcing agency under a shared service agreement) (town fire bureau)","Contact: Eric A. Stahl, Fire Marshal (Hardyston Fire Prevention Bureau), (973) 823-7020 Extension 9356, estahl@hardyston.com · (973) 823-7020 Option 7 · fireprevention@hardyston.com","Apply: Fee depends on business days before closing: more than 10 business days for the lowest fee. Inspections are good for 6 months. Sparta non-rushed inspections are Tuesdays 1PM to 3PM and Thursdays 8:30AM to 10:30AM; rushed inspections can be outside those windows. The Bureau contacts you within a few business days to schedule.","How to apply: Apply and pay online with the 'Byram and Sparta - CSACMAPFEC (Residential Smoke Cert)' form on the Hardyston Fire Prevention Bureau's payment portal, linked from Hardyston's CSACMAPFEC page (owner, closing date, block and lot, listing agent, rental or for sale by owner). Paper applications can be picked up at the Hardyston Township Municipal Building Construction Office window, 149 Wheatsworth Road, Hardyston. Phone (973) 823-7020 Option 7, fireprevention@hardyston.com.","Fire official in the NJ state directory, updated 1/29/2025: Eric Stahl · (973) 729-4227 · estahl@hardyston.com","All construction permits must be closed with the Construction Department (Building Department approval is needed before the smoke certification is scheduled)","Smoke alarms on each level and outside each separate sleeping area; 10 year sealed battery units, and AC powered alarms from original construction may not be replaced with battery alarms","Carbon monoxide alarm in the immediate vicinity of the sleeping areas, in homes with a fuel-burning device or attached garage","Secondary power source warning label within 18 inches of the main electrical panel and electrical meter (generators, solar, battery storage)","Fire extinguisher: Hardyston's regulations say it is no longer required, but Sparta's own Smoke Certifications page still says one must be mounted in the kitchen","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate (CSACMAPFEC), more than 10 business days before closing","amount":"$100.00"},{"label":"4 to 10 business days before closing","amount":"$150.00"},{"label":"Less than 4 business days before closing","amount":"$200.00"},{"label":"Re-inspection after a failed inspection (new request form needed)","amount":"$50.00"}]$j$::jsonb, $t$https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/5f651803-c7be-4f3f-beb6-41a7a004f5b1$t$, $t$https://hardyston.com/directories/fire-prevention-bureau/$t$, $j$[{"url":"https://www.spartanj.org/261/Fire-Marshal-Fire-Prevention","label":"Official source (spartanj.org)"},{"url":"https://www.spartanj.org/193/Smoke-Certifications","label":"Official source (spartanj.org)"},{"url":"https://hardyston.com/directories/fire-prevention-bureau/","label":"Official source (hardyston.com)"},{"url":"https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/5f651803-c7be-4f3f-beb6-41a7a004f5b1","label":"Official source (hardystonfireprebureaunj.tylerportico.com)"},{"url":"https://hardyston.com/wp-content/documents/forms/Regulations%20-%20CSACMAPFEC%20(Residential%20Smoke%20Cert).pdf","label":"Official source (hardyston.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Sparta Township has entered into a shared service agreement with the Township of Hardyston Fire Prevention Bureau.$t$, $t$9eadfca1687d2249d52446c9c7db33d21b2d542c7a6916dca861e6ce292118aa$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1918.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1918.json$t$, true),
  ($t$1919$t$, $t$Stanhope Borough$t$, $t$SUSSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitability (resale inspection)$t$, $j$["Issued by: Borough of Stanhope Construction Department (Housing Officer under Code Chapter 95)","Contact: Thomas Pershouse, Construction Official · 973-347-0159 ext. 20 · construction@stanhopenj.gov","Apply: The Code says the inspection is made no more than 20 days after the application is received. Inspections are by appointment on Wednesday evenings (5 to 7 pm) and Saturday mornings (9 am to 12 noon).","How to apply: Download the Resale Inspection Application (Application for Certificate of Habitability, Resale) from the Construction Department page, fill it in and return it with a $125.00 check payable to Borough of Stanhope to the Construction Department, 77 Main Street, Stanhope, NJ 07874. The office then schedules the inspection (Wednesday evenings or Saturday mornings).","Certificate of Habitability inspection before closing; no new owner may occupy until it is issued","Smoke detector on each floor, including the basement","At least one carbon monoxide detector outside a bedroom","ABC type fire extinguisher no larger than 10 lbs within 10 feet of the kitchen area (form still lists it)","All partitions put up by the current or a past owner must be removed before the certificate is issued","Condominiums must provide a copy of the listing showing the number of bedrooms","Application lists property location, block and lot, number of bedrooms, owner, agent, buyer's name and address, and tentative closing date","Also: Final water and sewer reading: The Water and Sewer Department posts a House Closing Data Sheet / Final Water Reading Request form for closings (Billing Clerk Tammy Minniti, 973-347-0159 ext. 10)."]$j$::jsonb, $j$[{"label":"Certificate of Habitability resale inspection (each resale)","amount":"$125.00"},{"label":"Certificate of habitability, resale (Code Chapter 82 fee schedule)","amount":"$125"}]$j$::jsonb, $t$https://stanhopenj.gov/wp-content/uploads/2022/07/Resale-Smoke-Cert.pdf$t$, $t$https://stanhopenj.gov/departments-and-services/municipal-departments/construction-department/$t$, $j$[{"url":"https://stanhopenj.gov/departments-and-services/municipal-departments/construction-department/","label":"Official source (stanhopenj.gov)"},{"url":"https://ecode360.com/10120475","label":"Official source (ecode360.com)"},{"url":"https://stanhopenj.gov/wp-content/uploads/2022/07/Resale-Smoke-Cert.pdf","label":"Official source (stanhopenj.gov)"},{"url":"https://ecode360.com/10120324","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$All properties being sold must have a Certificate of Habitability Inspection conducted prior to the closing.$t$, $t$9ee3c9ff47fa58f3d37fcbf5fa942307151741f840ffcb624fbe85f8e1515b2d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":8,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1919.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1919.json$t$, true),
  ($t$1919$t$, $t$Stanhope Borough$t$, $t$SUSSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Stanhope Construction Department (Certificate of Habitability resale inspection; fire code enforcing agency is the Sussex County Fire Marshal)","Contact: Thomas Pershouse, Construction Official · 973-347-0159 ext. 20 · construction@stanhopenj.gov","Apply: Inspections by appointment on Wednesday evenings and Saturday mornings. No rush-fee tiers are published.","How to apply: Use the same Resale Inspection Application as the Certificate of Habitability; there is no separate Borough smoke certificate form. Mail or drop off at the Construction Department, 77 Main Street, with a check payable to Borough of Stanhope.","Fire official in the NJ state directory (county fire marshal), updated 1/21/2026: Mark Snook · (973) 579-0380 · msnook@sussexcountysheriff.com","Smoke detector on each floor, including the basement","At least one carbon monoxide detector outside a bedroom","ABC type fire extinguisher no larger than 10 lbs within 10 feet of the kitchen area (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Habitability resale inspection, which includes the smoke/CO/extinguisher check","amount":"$125.00"}]$j$::jsonb, $t$https://stanhopenj.gov/wp-content/uploads/2022/07/Resale-Smoke-Cert.pdf$t$, $t$https://stanhopenj.gov/departments-and-services/municipal-departments/construction-department/$t$, $j$[{"url":"https://stanhopenj.gov/departments-and-services/municipal-departments/construction-department/","label":"Official source (stanhopenj.gov)"},{"url":"https://stanhopenj.gov/wp-content/uploads/2022/07/Resale-Smoke-Cert.pdf","label":"Official source (stanhopenj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Click Here for the Resale Inspection Application$t$, $t$ef21c2730160affe6583db11e894b305a9a44fe65a522f48a2c4d3e41e8c5b64$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":8,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1919.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1919.json$t$, true),
  ($t$1921$t$, $t$Sussex Borough$t$, $t$SUSSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitability for Resale (certificate of occupancy for a new owner)$t$, $j$["Issued by: Hardyston Township Fire Prevention Bureau (Hardyston Fire Marshal) under a shared service agreement; the Borough Code assigns the certificate of occupancy to the Sussex Borough Zoning Officer","Contact: George Hutnick, Zoning, Housing, Code Enforcement Officer · 973-875-4831 · zoning@sussexboro.com","Apply: Hardyston contacts the applicant within a few business days to schedule. Sussex non-rushed inspections are Wednesdays 8 to 9 am and Thursdays 1 to 3 pm; rushed inspections can be outside those windows. The Borough Code says a certificate of occupancy is granted or denied within 15 days of a written application.","How to apply: Use the Certificate of Habitability Resale link on the Borough's Zoning/Housing page, which opens the Hardyston Fire Prevention Bureau's online form (Sussex and Wantage - CSACMAPFEC). Enter owner, closing date, occupant, address and block/lot, and pay online. Paper applications can be picked up at the Hardyston Township Municipal Building Construction Office window, 149 Wheatsworth Road, Hardyston.","Valid for: Inspections are good for 6 months (Hardyston application page)","Resale inspection through the Hardyston Fire Marshal before the new owner occupies","Smoke alarms on each level and outside each sleeping area; 10-year sealed battery units unless hardwired","Carbon monoxide alarms near sleeping areas where there is a fuel-burning device or attached garage","Warning label within 18 inches of the main electrical panel and meter if the home has a generator, solar panels or battery storage","All construction permits must be closed with the Construction Department","Also: Sewer discharge certificate of compliance: Before title transfers on any property with a building connected to the Borough sewer, the owner must get a certificate of compliance from the Zoning Officer (no prohibited discharges such as sump pumps or roof drains into the sanitary sewer). Inspection fee $50, paid before the inspection, on a Borough form.","Also: Open construction permits: All construction permits must be closed with the Construction Department (Hardyston Building Department, which runs the Borough's construction office) before the smoke/resale certificate."]$j$::jsonb, $j$[{"label":"Certificate of habitability (COH) resale, each dwelling unit, request at least 10 business days before change of occupancy (Borough Code 24-1.5i3)","amount":"$50"},{"label":"COH resale, request 4 to 10 business days before change of occupancy (Borough Code)","amount":"$85"},{"label":"COH resale, request less than 4 business days before change of occupancy (Borough Code)","amount":"$150"},{"label":"Residential smoke/CO certificate (CSACMAPFEC), more than 10 business days before closing","amount":"$100.00"},{"label":"4 to 10 business days before closing","amount":"$150.00"},{"label":"Less than 4 business days before closing","amount":"$200.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/2b74a8ef-9b79-48b3-9ca2-4111720084aa$t$, $t$https://www.sussexboro.com/directory/zoning/$t$, $j$[{"url":"https://www.sussexboro.com/directory/zoning/","label":"Official source (sussexboro.com)"},{"url":"https://ecode360.com/36297675","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/36344313","label":"Official source (ecode360.com)"},{"url":"https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/2b74a8ef-9b79-48b3-9ca2-4111720084aa","label":"Official source (hardystonfireprebureaunj.tylerportico.com)"}]$j$::jsonb, $t$Accordingly, all resale inspections will be conducted through the Hardyston Fire Marshal.$t$, $t$7f183ec1236098db7f8137a7b440e2998dd580d4e2decb78e46da1499518c859$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":0,"fee_bad":0,"fee_unchecked":11,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1921.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1921.json$t$, true),
  ($t$1921$t$, $t$Sussex Borough$t$, $t$SUSSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hardyston Fire Prevention Bureau (shared service fire code agency for Sussex Borough) (town fire bureau)","Contact: Eric A. Stahl, Fire Marshal (Bureau line 973-823-7020 option 7, fireprevention@hardyston.com) · 973-823-7020 ext. 9356 · estahl@hardyston.com","Apply: Fee tiers count business days before closing: more than 10 business days for the lowest fee. Sussex non-rushed inspections are Wednesdays 8 to 9 am and Thursdays 1 to 3 pm. Inspections are good for 6 months.","How to apply: Apply and pay online through the Hardyston Fire Prevention Bureau portal (Sussex and Wantage - CSACMAPFEC form). A representative contacts you by phone or email to schedule. Paper applications are at the Hardyston Township Municipal Building Construction Office window. A failed inspection needs a new request and a $50.00 re-inspection fee.","Fire official in the NJ state directory (town), updated 9/8/2025: Eric A Stahl · (973) 823-7020 · estahl@hardyston.com","Smoke alarms on each level and outside each separate sleeping area (NFPA 72); not required to be interconnected, but hardwired interconnected alarms from construction must stay that way","10-year sealed battery smoke alarms (ANSI/UL 217); A/C powered alarms from original construction may not be replaced with battery alarms","Carbon monoxide alarms (UL 2034) in the immediate vicinity of sleeping areas where there is a fuel-burning device or attached garage","Secondary power source warning label (for example \"CAUTION: MULTIPLE SOURCES OF POWER.\") within 18 inches of the main electrical panel and meter if the home has a permanent generator, solar panels or battery storage","All construction permits must be closed with the Construction Department","No portable fire extinguisher is required","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Residential smoke/CO certificate (CSACMAPFEC), more than 10 business days before closing","amount":"$100.00"},{"label":"4 to 10 business days before closing","amount":"$150.00"},{"label":"Less than 4 business days before closing","amount":"$200.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/2b74a8ef-9b79-48b3-9ca2-4111720084aa$t$, $t$https://www.sussexboro.com/directory/fireprevention/index.shtml$t$, $j$[{"url":"https://www.sussexboro.com/directory/fireprevention/index.shtml","label":"Official source (sussexboro.com)"},{"url":"https://hardyston.com/directories/building-and-code-enforcement/fire-prevention-bureau/","label":"Official source (hardyston.com)"},{"url":"https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/2b74a8ef-9b79-48b3-9ca2-4111720084aa","label":"Official source (hardystonfireprebureaunj.tylerportico.com)"},{"url":"https://hardyston.com/wp-content/documents/forms/Regulations%20-%20CSACMAPFEC%20(Residential%20Smoke%20Cert).pdf","label":"Official source (hardyston.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Sussex Borough has entered into a shared service agreement with the Township of Hardyston Fire Prevention Bureau.$t$, $t$8b47c77a67482904c7554d0ba8ed1be5fd0e355e187c9d4690be1a25cee8a146$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":0,"fee_bad":0,"fee_unchecked":11,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1921.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1921.json$t$, true),
  ($t$1922$t$, $t$Vernon Township$t$, $t$SUSSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Dwelling Re-occupancy Inspection / Re-occupancy Certificate$t$, $j$["Issued by: Vernon Township Department of Fire Prevention (Fire Prevention Bureau)","Contact: Tom VanLeuven, Fire Marshal (ext. 2271) · 973-764-4055 ext. 2272 · firemarshal@vernontwp.com","Apply: Fee tiers count business days between the Fire Prevention Bureau's receipt of the application and the closing; more than 10 business days for the lowest fee. Mailed applications count from the day the Bureau receives them. The inspection is scheduled once the completed application and fee are received.","How to apply: Fill in three forms completely: the Re-occupancy & Smoke Detector Certification Application (Fire Prevention), the Construction Records Clearance Application (Building Department) and the Vacant & Abandoned Residential Properties Approval Sheet (signed by the Zoning Officer or Clerk). Drop them off or mail them with payment to Vernon Township, 21 Church Street, Vernon, NJ 07462. Fire Prevention takes exact cash, check or money order payable to Vernon Township. An after-hours drop box is at the rear of the building by the police station (no cash). Fire Prevention then schedules the inspection.","Re-occupancy inspection before a 1 or 2 family dwelling is sold, leased or changes occupancy (Code Section 250-21)","Working smoke detectors on each level and outside each separate sleeping area; battery units must be 10-year sealed; hardwired units must be replaced with hardwired","Carbon monoxide alarms within 10 feet of a bedroom on each level","At least one portable fire extinguisher, no more than 10 lbs, labeled 2A10BC, within 10 feet of the kitchen (Township page still lists it)","Property maintenance and compliance with Township ordinances","Structure must match Tax Assessor and Building Department records; open permits must be inspected and closed","Construction Records Clearance Application filed with the Building Department","Vacant and Abandoned Residential Properties Approval Sheet signed by the Zoning Officer or the Clerk's office, for every re-occupancy request","Also: Construction Records Clearance: Building Department review of permit records for the sale (asks about address display, pool, pool fence, finished basement and second kitchen). Fee $40.00 more than 10 calendar days before closing, $75.00 within 10 days, $125.00 within 4 days. Submit with payment to Vernon Building Department, 21 Church Street.","Also: Vacant and abandoned property sign-off: The Vacant and Abandoned Residential Properties Approval Sheet must be signed by the Zoning Officer or the Clerk's office before the re-occupancy inspection is scheduled, even if the home is not vacant."]$j$::jsonb, $j$[{"label":"Re-occupancy and smoke detector certificate, request received more than 10 business days before the change of occupancy","amount":"$100.00"},{"label":"Request received 5 to 10 business days before the change of occupancy","amount":"$150.00"},{"label":"Request received 4 business days or less before the change of occupancy","amount":"$200.00"},{"label":"Re-occupancy checklist review and inspection (Code fee quoted on the Township page)","amount":"$25"},{"label":"Construction Records Clearance, request more than 10 calendar days before closing","amount":"$40.00"},{"label":"Construction Records Clearance, request within 10 calendar days of closing","amount":"$75.00"},{"label":"Construction Records Clearance, request within 4 calendar days of closing","amount":"$125.00"}]$j$::jsonb, $t$https://www.vernontwp.com/images/FP_Reoccup_Applic_7312026.pdf$t$, $t$https://www.vernontwp.com/index.php/services/reoccupancy-inspections$t$, $j$[{"url":"https://www.vernontwp.com/index.php/services/reoccupancy-inspections","label":"Official source (vernontwp.com)"},{"url":"https://www.vernontwp.com/index.php/government/departments/fire-prevention","label":"Official source (vernontwp.com)"},{"url":"https://www.vernontwp.com/images/FP_Reoccup_Applic_7312026.pdf","label":"Official source (vernontwp.com)"},{"url":"https://www.vernontwp.com/images/Construction_Records_Clearance_Form.pdf","label":"Official source (vernontwp.com)"},{"url":"https://vernontwp.com/images/Vacant__Abandoned_Residential_Property.pdf","label":"Official source (vernontwp.com)"},{"url":"https://www.vernontwp.com/index.php/services/fire-inspections","label":"Official source (vernontwp.com)"}]$j$::jsonb, $t$Pursuant to §250-21 of the Vernon Township Code, before a 1- or 2-family residential dwelling is sold, leased or a change of occupancy occurs, the dwelling must be inspected.$t$, $t$6afdf156c7164e132d443967c1098722a14c8f72b65c182e16067b372efd1011$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":7,"fee_bad":0,"fee_unchecked":3,"quotes":18,"q_ok":14,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1922.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1922.json$t$, true),
  ($t$1922$t$, $t$Vernon Township$t$, $t$SUSSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Vernon Township Department of Fire Prevention (Fire Prevention Bureau) (town fire bureau)","Contact: Tom VanLeuven, Fire Marshal · 973-764-4055 ext. 2271 · firemarshal@vernontwp.com","Apply: Fee depends on business days between the Bureau's receipt of the application and the change of occupancy; more than 10 business days for the lowest fee.","How to apply: Same combined Re-occupancy & Smoke Detector Certification Application as the re-occupancy certificate, filed with the Construction Records Clearance Application and the signed Vacant & Abandoned sheet at 21 Church Street, Vernon. Pay by exact cash, check or money order to Vernon Township.","Fire official in the NJ state directory (town), updated 6/4/2026: Tom VanLeuven · (973) 764-4055 · tvanleuven@vernontwp.com","Smoke detectors on each level of the premises and outside each separate sleeping area","Battery smoke and CO detectors must be 10-year sealed (tamper resistant); hardwired detectors must be replaced with hardwired","Carbon monoxide alarms within 10 feet of a bedroom on each level","Smoke and CO detectors in condo lofts","At least one portable fire extinguisher, no more than 10 lbs, 2A10BC label, within 10 feet of the kitchen (Township page still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Re-occupancy and smoke detector certificate, request received more than 10 business days before the change of occupancy","amount":"$100.00"},{"label":"Request received 5 to 10 business days before the change of occupancy","amount":"$150.00"},{"label":"Request received 4 business days or less before the change of occupancy","amount":"$200.00"}]$j$::jsonb, $t$https://www.vernontwp.com/images/FP_Reoccup_Applic_7312026.pdf$t$, $t$https://www.vernontwp.com/index.php/government/departments/fire-prevention$t$, $j$[{"url":"https://www.vernontwp.com/index.php/government/departments/fire-prevention","label":"Official source (vernontwp.com)"},{"url":"https://www.vernontwp.com/index.php/services/reoccupancy-inspections","label":"Official source (vernontwp.com)"},{"url":"https://www.vernontwp.com/index.php/services/fire-inspections","label":"Official source (vernontwp.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$conducts reoccupancy and smoke detector inspections when a home is sold, leased or a change of occupancy occurs$t$, $t$3108b2f8b7135581f427611078c0565740b6cde07ae1fa240c63c68c5ab6e80f$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":7,"fee_bad":0,"fee_unchecked":3,"quotes":18,"q_ok":14,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1922.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1922.json$t$, true),
  ($t$1924$t$, $t$Wantage Township$t$, $t$SUSSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Habitability (resale)$t$, $j$["Issued by: Wantage Township (historically the zoning/code enforcement office); the current Township site sends resale smoke/CO inspections to the Hardyston Fire Prevention Bureau","Contact: Andrew Coccio, Zoning/Code Enforcer · 973-875-7195 (option 7) · andrew@wantagetwp-nj.org","How to apply: The Township's live Forms and Fire Prevention pages link only to the Hardyston Fire Prevention Bureau's online CSACMAPFEC form (Sussex and Wantage) for resales; no current Township Certificate of Habitability application is linked. Call the Zoning Office (973-875-7195, option 7) to confirm whether a separate Continued Certificate of Habitability inspection is still done.","Visual safety inspection (older Township checklist): no work done without permits","Working smoke detectors on each level, including basement and walk-up attic; CO detector in the common area outside bedrooms","Fire extinguisher within 10 feet of the kitchen, mounted (older checklist still lists it)","Relief valve pipes on water heater and boiler within 6 inches of the floor; handrails/guardrails for more than four steps","Switch and outlet covers in place, no exposed wiring or open boxes, electric panel with no openings; GFIs working where originally installed","Sound stairs, no holes in attached garage walls or ceilings, working toilets and faucets, hot water at least 110 degrees","Proper venting of furnace/boiler and water heater, metal or UL listed foil dryer vents, bathroom ventilation","No broken windows, illegal conversions or illegal living areas; working septic and well/water","House number 4 to 8 inches high","Also: Open construction permits: All construction permits must be closed with the Construction Department before the smoke/CO certificate. Wantage's construction office is run by Hardyston Township under a shared service agreement (973-875-7195 option 6, construction@hardyston.com)."]$j$::jsonb, $j$[{"label":"Certificate of Habitability, resales, each dwelling unit, request at least 10 business days before change of occupancy (Township Code 21-4 fee table)","amount":"$80"},{"label":"Request less than 10 but more than 4 business days before change of occupancy (Code)","amount":"$85"},{"label":"Request less than 4 business days before change of occupancy (Code)","amount":"$150"}]$j$::jsonb, $t$https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/2b74a8ef-9b79-48b3-9ca2-4111720084aa$t$, $t$https://wantagetwp.com/departments/zoning/$t$, $j$[{"url":"https://wantagetwp.com/forms/ContinuedCertificateofHabitabilityVisualInspectionList.pdf","label":"Official source (wantagetwp.com)"},{"url":"https://ecode360.com/36051528","label":"Official source (ecode360.com)"},{"url":"https://wantagetwp.com/departments/zoning/","label":"Official source (wantagetwp.com)"}]$j$::jsonb, $t$A Continued Certificate of Habitability is required on all re-sales, rentals, and/or changes or tenancy.$t$, $t$cd7d7e24f8a3cd215fe6a39437f75f16e9b6e5ebb9bfa1962835970e1b5e366f$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":14,"q_ok":10,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1924.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1924.json$t$, true),
  ($t$1924$t$, $t$Wantage Township$t$, $t$SUSSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hardyston Fire Prevention Bureau (shared service fire code agency for Wantage Township) (town fire bureau)","Contact: Eric A. Stahl, Fire Marshal (Bureau line 973-823-7020 option 7, fireprevention@hardyston.com) · 973-823-7020 ext. 9356 · estahl@hardyston.com","Apply: Fee tiers count business days before closing: more than 10 business days for the lowest fee. Wantage non-rushed inspections are Tuesdays 8 to 9 am and Thursdays 1 to 3 pm. Inspections are good for 6 months.","How to apply: Apply and pay online through the Hardyston Fire Prevention Bureau portal (Sussex and Wantage - CSACMAPFEC form), linked from Wantage's Fire Prevention and Forms pages. A representative contacts you to schedule within a few business days. Paper applications are at the Hardyston Township Municipal Building Construction Office window, 149 Wheatsworth Road. Online payments add a processing fee.","Fire official in the NJ state directory (town), updated 7/28/2026: Eric A Stahl · (973) 823-7020 · estahl@hardyston.com","Smoke alarms on each level and outside each separate sleeping area (NFPA 72); hardwired interconnected alarms from construction must stay that way","10-year sealed battery smoke alarms (ANSI/UL 217); A/C powered alarms from original construction may not be replaced with battery alarms","Carbon monoxide alarms (UL 2034) in the immediate vicinity of sleeping areas where there is a fuel-burning device or attached garage","Secondary power source warning label within 18 inches of the main electrical panel and meter if the home has a permanent generator, solar panels or battery storage","All construction permits must be closed with the Construction Department","No portable fire extinguisher is required","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Residential smoke/CO certificate (CSACMAPFEC), more than 10 business days before closing","amount":"$100.00"},{"label":"4 to 10 business days before closing","amount":"$150.00"},{"label":"Less than 4 business days before closing","amount":"$200.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/2b74a8ef-9b79-48b3-9ca2-4111720084aa$t$, $t$https://wantagetwp.com/departments/fireprevention/$t$, $j$[{"url":"https://wantagetwp.com/departments/fireprevention/","label":"Official source (wantagetwp.com)"},{"url":"https://hardystonfireprebureaunj.tylerportico.com/payments/billsearch/miscellaneous-payments/2b74a8ef-9b79-48b3-9ca2-4111720084aa","label":"Official source (hardystonfireprebureaunj.tylerportico.com)"},{"url":"https://hardyston.com/wp-content/documents/forms/Regulations%20-%20CSACMAPFEC%20(Residential%20Smoke%20Cert).pdf","label":"Official source (hardyston.com)"},{"url":"https://hardyston.com/directories/building-and-code-enforcement/fire-prevention-bureau/","label":"Official source (hardyston.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Wantage Township has entered into a shared service agreement with the Township of Hardyston Fire Prevention Bureau.$t$, $t$3e97559cc77ae5f719eb10d99e43b65d2bfb4a1b78ae05679c3be8bbb093177b$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":14,"q_ok":10,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1924.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1924.json$t$, true)
